```kotlin
class PaymentService(private val gateway: PaymentGateway, private val orders: OrderRepository) {
    private val log = LoggerFactory.getLogger(PaymentService::class.java)

    fun capture(orderId: String, card: CardDetails, gatewayToken: String): CaptureResult {
        return try {
            gateway.capture(gatewayToken, card.number, orders.totalFor(orderId))
        } catch (e: GatewayException) {
            log.error("error occurred")
            CaptureResult.Declined
        }
    }
}
```

`CardDetails` holds the card number, expiry and cardholder name. `gatewayToken` is the payment provider's charge token for this order. The catch block returns `Declined` to the caller, which shows the customer a retry screen; nothing above it logs the failure.
